293→            &env,
294→            &volumes,
295→        );
296→        assert_eq!(args[0], "create");
297→        assert_eq!(args[1], "--name");
298→        assert_eq!(args[2], "dual-lightfast-main");
299→        assert_eq!(args[3], "-v");
300→        assert!(args[4].contains("/home/user/dual-workspaces/lightfast/main:/workspace"));
301→        assert_eq!(args[5], "-v");
302→        assert_eq!(args[6], "/workspace/node_modules");
303→        assert_eq!(args[7], "-w");
304→        assert_eq!(args[8], "/workspace");
