249→```rust
250→fn cmd_sync(workspace_arg: Option<String>) -> i32 {
251→    let st = match state::load() { ... };
252→
253→    // Resolve which workspace we're syncing
254→    let entry = if let Some(ws) = workspace_arg {
255→        // Explicit workspace argument
256→        match st.resolve_workspace(&ws) {
257→            Some(e) => e.clone(),
258→            None => { eprintln!("error: unknown workspace '{ws}'"); return 1; }
259→        }
260→    } else {
261→        // Detect from current directory
262→        match detect_workspace(&st) {
263→            Some(e) => e.clone(),
264→            None => {
265→                eprintln!("error: not inside a dual workspace");
266→                eprintln!("Usage: dual sync [workspace]");
267→                return 1;
268→            }
269→        }
270→    };
271→
272→    // Load hints
273→    let workspace_dir = st.workspace_dir(&entry);
274→    let hints = config::load_hints(&workspace_dir).unwrap_or_default();
275→    let shared_config = match &hints.shared {
276→        Some(s) if !s.files.is_empty() => s,
277→        _ => {
278→            eprintln!("error: no [shared] section in .dual.toml (or files list is empty)");
279→            return 1;
280→        }
281→    };
282→
283→    let shared_dir = match shared::ensure_shared_dir(&entry.repo) {
284→        Ok(d) => d,
285→        Err(e) => { eprintln!("error: {e}"); return 1; }
286→    };
287→
288→    let is_main = entry.path.is_some();
289→
290→    if is_main {
291→        // Main workspace: init shared dir, then prompt to sync all branches
292→        match shared::init_from_main(&workspace_dir, &shared_dir, &shared_config.files) {
293→            Ok(moved) => {
294→                for f in &moved { println!("  moved {f} → shared/"); }
295→            }
296→            Err(e) => { eprintln!("error: {e}"); return 1; }
297→        }
298→
299→        // Prompt to sync all branches
300→        let branches: Vec<_> = st.workspaces_for_repo(&entry.repo)
301→            .into_iter()
302→            .filter(|ws| ws.path.is_none())
303→            .collect();
304→
305→        if branches.is_empty() {
306→            println!("No branch workspaces to sync.");
307→            return 0;
308→        }
309→
310→        println!("\nSync shared files to ALL {} branch workspace(s)? [y/N]", branches.len());
311→        let mut input = String::new();
312→        std::io::stdin().read_line(&mut input).unwrap_or(0);
313→        if !input.trim().eq_ignore_ascii_case("y") {
314→            println!("Cancelled.");
315→            return 0;
316→        }
317→
318→        for branch_entry in &branches {
319→            let branch_dir = st.workspace_dir(branch_entry);
320→            if !branch_dir.exists() {
321→                continue; // Not yet cloned
322→            }
323→            let ws_id = config::workspace_id(&branch_entry.repo, &branch_entry.branch);
324→            match shared::copy_to_branch(&branch_dir, &shared_dir, &shared_config.files) {
325→                Ok(copied) => {
326→                    println!("{ws_id}: synced {} file(s)", copied.len());
327→                }
328→                Err(e) => eprintln!("{ws_id}: error: {e}"),
329→            }
330→        }
331→    } else {
332→        // Branch workspace: copy from shared dir
333→        match shared::copy_to_branch(&workspace_dir, &shared_dir, &shared_config.files) {
334→            Ok(copied) => {
335→                if copied.is_empty() {
336→                    println!("No shared files available yet. Run `dual sync` in the main workspace first.");
337→                } else {
338→                    for f in &copied { println!("  synced {f}"); }
339→                }
340→            }
341→            Err(e) => { eprintln!("error: {e}"); return 1; }
342→        }
343→    }
344→
345→    0
346→}
347→```
