353→```rust
354→/// Detect which workspace the current directory belongs to.
355→fn detect_workspace(st: &state::WorkspaceState) -> Option<state::WorkspaceEntry> {
356→    let cwd = std::env::current_dir().ok()?;
357→
358→    // Try git root first (handles being in subdirectories)
359→    let root = std::process::Command::new("git")
360→        .args(["rev-parse", "--show-toplevel"])
361→        .output()
362→        .ok()
363→        .filter(|o| o.status.success())
364→        .map(|o| PathBuf::from(String::from_utf8_lossy(&o.stdout).trim().to_string()))
365→        .unwrap_or(cwd);
366→
367→    for ws in st.all_workspaces() {
368→        let ws_dir = st.workspace_dir(ws);
369→        if ws_dir == root {
370→            return Some(ws.clone());
371→        }
372→    }
373→    None
374→}
375→```
